  "kind": "beast.source_patch.v1",
  "operations": [
    {
      "op": "replace_exact",
      "op_id": "op_001",
      "path": "app/provider_parser.py",
      "old": "def normalize_provider_id(value):\n    return str(value or \"\").lower()",
      "new": "def normalize_provider_id(value):\n    value = str(value or \"\").strip()\n    value = value.replace('-', '_').replace(' ', '_').lower()\n    return value",
      "why": "Enhance normalization to handle hyphens and spaces by replacing them with underscores and converting to lowercase."
    }
  ],
  "tests": ["python -m pytest tests -q"]
}

